-- ───────── 약관 마스터 (버전별 1행) ─────────
CREATE TABLE "terms" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "type" varchar NOT NULL,
  "version" int NOT NULL,
  "title" varchar NOT NULL,
  "required" boolean NOT NULL,
  "content_path" varchar,
  "display_order" int NOT NULL,
  "effective_at" timestamp NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "deleted_at" timestamp
);
CREATE UNIQUE INDEX uq_terms_type_version ON "terms" ("type", "version");

COMMENT ON TABLE "terms" IS '약관 마스터. 개정하면 같은 type에 version을 올린 새 행을 추가한다';
COMMENT ON COLUMN "terms"."type" IS 'AGE_14 / SERVICE / PRIVACY / LOCATION / SAFETY / NOTIFICATION / NIGHT_PUSH';
COMMENT ON COLUMN "terms"."version" IS '약관 버전 (type별 1부터)';
COMMENT ON COLUMN "terms"."title" IS '체크박스 문구 ([필수]/[선택] 접두어 제외, 프론트가 required로 붙인다)';
COMMENT ON COLUMN "terms"."required" IS '필수 동의 여부';
COMMENT ON COLUMN "terms"."content_path" IS '약관 전문 markdown의 classpath 경로 (전문 없으면 null)';
COMMENT ON COLUMN "terms"."display_order" IS '화면 표시 순서';
COMMENT ON COLUMN "terms"."effective_at" IS '시행 시각 (이 시각부터 현재 약관)';

-- ───────── 사용자 동의 이력 ─────────
CREATE TABLE "user_terms_agreement" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "terms_id" bigint NOT NULL,
  "agreed" boolean NOT NULL,
  "agreed_at" timestamp NOT NULL,
  "created_at" timestamp NOT NULL,
  "updated_at" timestamp NOT NULL,
  "deleted_at" timestamp
);
ALTER TABLE "user_terms_agreement" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id");
ALTER TABLE "user_terms_agreement" ADD FOREIGN KEY ("terms_id") REFERENCES "terms" ("id");
CREATE INDEX idx_user_terms_agreement_user ON "user_terms_agreement" ("user_id", "terms_id", "agreed_at");

COMMENT ON TABLE "user_terms_agreement" IS '동의·철회 이력. 수정하지 않고 새 행 추가';
COMMENT ON COLUMN "user_terms_agreement"."agreed" IS '동의 여부 (선택 약관 미동의도 false로 남긴다)';
COMMENT ON COLUMN "user_terms_agreement"."agreed_at" IS '동의(또는 철회) 시각';

-- ───────── 사용자 상태 ─────────
ALTER TABLE "users" ADD COLUMN "onboarding_completed_at" timestamp;
ALTER TABLE "users" ADD COLUMN "notification_enabled" boolean NOT NULL DEFAULT false;
ALTER TABLE "users" ADD COLUMN "night_push_consent" boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN "users"."onboarding_completed_at" IS '온보딩(약관 동의 + 본인인증) 완료 시각. null이면 미완료';
COMMENT ON COLUMN "users"."notification_enabled" IS '활동 알림 수신 동의 (동의 전에는 알림을 보내지 않는다)';
COMMENT ON COLUMN "users"."night_push_consent" IS '야간(22시~08시) 푸시 수신 동의';

